package com.cybershield.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserDetailsService uds; public JwtFilter(JwtService jwt,UserDetailsService uds){this.jwt=jwt;this.uds=uds;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){try{var u=uds.loadUserByUsername(jwt.extractEmail(t));var a=new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities());SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}}} chain.doFilter(req,res);} }
